import { DAYS, SLOT_DEFS } from './scheduler.js';

const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

export function renderShell() {
  return `<aside class="rail"><button class="rail-home active" aria-label="Home" title="Home">⌂</button><button class="rail-menu" aria-label="Open navigation">☰</button><nav><button class="rail-item active" data-view="class" title="Class Timetable">▦</button><button class="rail-item" data-view="teacher" title="Teacher Timetable">♙</button><button class="rail-item" data-view="lab" title="Lab Timetable">⚗</button></nav></aside><main class="workspace"><header class="topbar"><div><p class="eyebrow">SCHEDULER</p><h1>Class Timetable</h1></div><div class="top-actions"><select id="class-selector" disabled><option>Upload data to load classes.</option></select><button id="generate-button" class="button primary" disabled>Regenerate Selected Class</button></div></header><section id="content" class="canvas"></section></main><div id="toast-region" class="toast-region" aria-live="polite"></div>`;
}

export function renderSetup(model = null) {
  const file = model?.filename ? `<div class="upload-success"><span>✓</span><span>${esc(model.filename)}</span></div>` : '';
  const classSubjects = model?.activeClass ? model.subjects.filter(subject => subject.className === model.activeClass) : (model?.subjects || []);
  const classTeacherNames = new Set(classSubjects.flatMap(subject => String(subject.teacher || '').split(/[,;]/).map(name => name.trim()).filter(Boolean)));
  const classStaff = (model?.staff || []).filter(person => classTeacherNames.has(person.name));
  const staff = classStaff.length ? `<section class="card staff-card"><div class="section-kicker">03 / STAFF RULES · ${esc(model.activeClass || '')}</div><h2>Staff and first-hour rules</h2><p>HOD and CC roles apply only to the selected class. Active roles are excluded from Period 1 for that class.</p><div class="staff-list">${classStaff.map(person => { const hod = person.hodFor?.includes(model.activeClass) || (person.isHod && !person.hodFor); const cc = person.ccFor?.includes(model.activeClass); return `<div class="staff-row"><div><strong>${esc(person.name)}</strong><small>${esc(person.initials || '')}</small></div><button class="staff-toggle ${hod ? 'selected' : ''}" data-staff-hod="${esc(person.name)}" aria-pressed="${hod}">${hod ? 'HOD · On' : 'HOD · Off'}</button><button class="staff-toggle ${cc ? 'selected' : ''}" data-staff-cc="${esc(person.name)}" aria-pressed="${cc}">${cc ? 'CC · On' : 'CC · Off'}</button></div>`; }).join('')}</div></section>` : '';
  const labs = classSubjects.filter(subject => subject.labPeriods > 0);
  const theory = classSubjects.filter(subject => subject.labPeriods === 0 && !subject.isExtracurricular);
  const extracurricular = classSubjects.filter(subject => subject.labPeriods === 0 && subject.isExtracurricular);
  const toggle = subject => `<label class="subject-toggle"><input type="checkbox" data-extracurricular="${esc(subject.id)}" ${subject.isExtracurricular ? 'checked' : ''}><span></span><b>Extracurricular</b></label>`;
  const subjectRow = subject => `<div class="subject-row"><span class="subject-code">${esc(subject.acronym || subject.code)}</span><div><strong>${esc(subject.name)}</strong><small>${esc(subject.code)} · ${esc(subject.teacher)}</small></div><b>${subject.theoryPeriods || 0} h</b>${toggle(subject)}</div>`;
  const labRows = labs.map(subject => { const lab = model.labs.find(item => item.subjectId === subject.id) || {}; const length = lab.length || lab.labPeriods || subject.labPeriods || 2; return `<div class="lab-entry-row"><div><span class="subject-code">${esc(subject.acronym || subject.code)}</span><strong>${esc(subject.name)}</strong><small>${esc(subject.code)} · ${esc(subject.teacher)} · ${length} continuous periods</small></div><label>Day<select data-lab-day="${esc(subject.id)}"><option value="">Auto</option>${DAYS.map(day => `<option value="${day}" ${lab.day === day ? 'selected' : ''}>${day}</option>`).join('')}</select></label></div>`; }).join('');
  const classifications = classSubjects.length ? `<section class="classification-wrap"><div class="classification-heading"><div class="section-kicker">04 / SUBJECT CLASSIFICATION</div><h2>Classify and place subjects · ${esc(model.activeClass || '')}</h2><p>Set fixed lab blocks and mark non-exam activities that must stay together on one day.</p></div><section class="card classification-card lab-classification"><div class="classification-title"><span>01</span><div><h3>Labs</h3><p>Choose the exact day, or leave it on Auto.</p></div></div><div class="lab-entry-list">${labRows || '<div class="empty-classification">No lab subjects in this class.</div>'}</div></section><section class="card classification-card"><div class="classification-title"><span>02</span><div><h3>Theory subjects</h3><p>Turn on Extracurricular for club, seminar, mentor, or other non-exam periods.</p></div></div><div class="subject-list">${theory.map(subjectRow).join('') || '<div class="empty-classification">All non-lab subjects are marked extracurricular.</div>'}</div></section><section class="card classification-card extracurricular-card"><div class="classification-title"><span>03</span><div><h3>Extracurricular subjects</h3><p>Every assigned hour stays together on one day starting at or after Period 3, without crossing a Break or Lunch period.</p></div></div><div class="subject-list">${extracurricular.map(subjectRow).join('') || '<div class="empty-classification">Toggle a theory subject to add it here.</div>'}</div></section></section>` : '';
  return `<div class="setup-grid"><section class="card upload-card"><div class="section-kicker">01 / IMPORT</div><h2>Import Excel Sheet</h2><p>Upload teacher, subject, and class allocation data.</p><label class="drop-zone" for="file-input"><span class="excel-mark">X</span><strong>Drop your workbook here</strong><small>or click to browse .xlsx files</small><input id="file-input" type="file" accept=".xlsx,.xls,.csv"></label>${file}<div id="upload-error" class="upload-error" hidden></div></section><section class="card template-card"><div class="section-kicker">02 / FORMAT</div><h2>Timetable format</h2><p>Choose the timetable view to generate.</p><div class="template-options"><button class="template-option selected" data-template="class"><span class="mini-grid">▦</span><strong>Class</strong><small>Official weekly class view</small></button><button class="template-option" data-template="teacher"><span class="mini-grid">♙</span><strong>Teacher</strong><small>Combined staff weekly view</small></button></div></section>${staff}${classifications}<section class="card helper-card"><details><summary><span><b>Required Columns</b><small>Validated during import</small></span><span class="chevron">⌄</span></summary><div class="chips"><span>Teacher Name</span><span>Subject Name</span><span>Subject Code</span><span>Class Name</span><span>Periods Required</span><span>Lab Day / Start / Length</span><span>Availability</span></div></details></section><section class="action-card"><div><strong>Ready to build a complete 48-period class timetable?</strong><span>Fixed labs, extracurricular blocks, first-hour rules, and hard conflicts are checked.</span></div><button id="validate-button" class="button primary" ${model ? '' : 'disabled'}>Validate &amp; Generate <span>→</span></button></section></div>`;
}

export function renderGenerated(schedule, model, diagnostics, schedules = null) {
  const errors = diagnostics.filter(d => d.severity === 'error').length;
  const warnings = diagnostics.filter(d => d.severity === 'warning').length;
  const selectedClass = String(schedule.className || '').trim();
  const classSubjects = model.subjects.filter(subject => String(subject.className || '').trim() === selectedClass);
  const header = SLOT_DEFS.map(slot => slot.teaching ? `<div class="slot-head"><span>P${slot.period + 1}</span><small>${slot.label}</small></div>` : `<div class="slot-head break-head"><span>${slot.label}</span></div>`).join('');
  const rows = DAYS.map(day => `<div class="grid-row"><div class="day-label">${day}</div>${SLOT_DEFS.map(slot => { if (!slot.teaching) return `<div class="grid-cell break-cell"><span>${slot.label}</span></div>`; const cell = schedule[day][slot.period]; const flagged = cell && diagnostics.some(d => d.subjectId === cell.subjectId && d.day === day && d.period === slot.period + 1); return `<button class="grid-cell ${cell?.lab ? 'lab-cell' : ''} ${cell?.kind === 'activity' ? 'activity-cell' : ''} ${flagged ? 'conflict-cell' : ''}" data-day="${day}" data-period="${slot.period}" data-subject="${esc(cell?.subjectId || '')}">${cell ? `<strong>${esc(cell.acronym || cell.subjectCode)}</strong><small>${esc(cell.teacher.split(/[,;]/)[0])}</small>${flagged ? '<i class="warning-dot"></i>' : ''}` : '<span class="empty-slot">—</span>'}</button>`; }).join('')}</div>`).join('');
  const subjectSummary = `<div class="placement-grid"><div class="placement-head"><span>SUBJECT / FACULTY</span>${DAYS.map(day => `<span>${day}</span>`).join('')}<span>TOTAL</span></div>${classSubjects.map(subject => { const dayCells = DAYS.map(day => { const cells = schedule[day].filter(cell => cell?.subjectId === subject.id); const labPeriods = cells.filter(cell => cell.kind === 'lab').map(cell => cell.period + 1); const theoryPeriods = cells.filter(cell => cell.kind === 'theory').map(cell => cell.period + 1); let label = theoryPeriods.map(period => `P${period}`).join(' · '); if (labPeriods.length) { const contiguous = labPeriods.every((period, index) => index === 0 || period === labPeriods[index - 1] + 1); const labLabel = contiguous ? `LB P${Math.min(...labPeriods)}–P${Math.max(...labPeriods)}` : labPeriods.map(period => `LB P${period}`).join(' · '); label = [label, labLabel].filter(Boolean).join(' + '); } return `<span class="placement-cell ${labPeriods.length ? 'placement-lab' : ''}">${label || '—'}</span>`; }).join(''); return `<div class="placement-row"><div><strong>${esc(subject.acronym || subject.code)}</strong><small>${esc(subject.name)}</small><small>${esc(subject.code)} · ${esc(subject.teacher)}</small></div>${dayCells}<b>${subject.theoryPeriods || 0}${subject.labPeriods ? ` + ${subject.labPeriods} LB` : ''} h</b></div>`; }).join('')}</div>`;
  const labRows = classSubjects.filter(subject => Number(subject.labPeriods) > 0).map(subject => `<div class="lab-grid-row"><div><strong>${esc(subject.acronym || subject.code)}</strong><small>${esc(subject.name)}</small></div>${DAYS.map(day => { const periods = schedule[day].filter(cell => cell?.subjectId === subject.id && cell.kind === 'lab').map(cell => cell.period + 1); return `<div class="lab-grid-cell">${periods.length ? `P${Math.min(...periods)}–P${Math.max(...periods)}` : '—'}</div>`; }).join('')}</div>`).join('');
  const filled = DAYS.reduce((total, day) => total + schedule[day].filter(Boolean).length, 0);
  const unallocated = DAYS.length * 8 - filled;
  const requestedHours = classSubjects.reduce((total, subject) => total + subject.theoryPeriods + subject.labPeriods, 0);
  const allocationSummary = `<section class="card allocation-summary"><div class="section-kicker">ALLOCATION REVIEW</div><h2>Unallocated periods by class</h2><p>Use Edit Subject / Teacher, then click an empty cell to assign a subject manually. System warnings are listed here instead of blocking the class view.</p><div class="allocation-list">${Object.values(schedules || { [selectedClass]: schedule }).map(item => { const empty = DAYS.flatMap(day => (item[day] || []).map((cell, period) => cell ? null : `${day} · P${period + 1}`).filter(Boolean)); const issues = diagnostics.filter(diagnostic => diagnostic.severity === 'error' && (diagnostic.className === item.className || (!diagnostic.className && item.className === selectedClass))); return `<div class="allocation-row ${item.className === selectedClass ? 'active' : ''}"><strong>${esc(item.className)}</strong><span>${empty.length ? `${empty.length} empty · ${empty.join(', ')}` : 'Complete · 48/48 periods'}</span>${issues.length ? `<div class="allocation-issues">${issues.map(issue => `<div>${esc(issue.message)}</div>`).join('')}</div>` : ''}</div>`; }).join('')}</div></section>`;
  const labPlan = `${allocationSummary}<section class="card lab-plan-card"><div class="section-kicker">LAB BLOCKS</div><h2>Continuous lab hours by day</h2><p>Lab periods are allocated as one continuous block. Theory periods are scheduled separately.</p><div class="lab-grid"><div class="lab-grid-head"><span>LAB</span>${DAYS.map(day => `<span>${day}</span>`).join('')}</div>${labRows || '<div class="empty-labs">No lab subjects in this class.</div>'}</div></section>`;
  const capacityMessage = unallocated
    ? (errors ? `${unallocated} slot(s) remain empty because the active hard constraints prevented exact placement.` : `${unallocated} slot(s) are unused because the requested workload is below 48 periods.`)
    : 'Every teaching slot is filled by an uploaded subject or lab.';
  const selectedErrors = diagnostics.filter(item => item.severity === 'error' && (item.className === selectedClass || !item.className) && !['R9', 'R2a'].includes(item.rule));
  const feasibilityBanner = selectedErrors.length
    ? `<section class="card feasibility-block"><div class="feasibility-title">⚠ Exact timetable not possible</div><p>No valid timetable could be constructed from this data — the workload cannot be satisfied exactly while respecting the hard rules below. Empty slots were left empty rather than filled with placeholders.</p><ul>${[...new Set(selectedErrors.map(item => item.message))].map(message => `<li>${esc(message)}</li>`).join('')}</ul></section>`
    : (errors ? `<section class="card feasibility-block"><div class="feasibility-title">⚠ Incomplete timetable</div><p>The solution below is the best found; it does not yet satisfy the exact workload. See the allocation review for the blocking reasons.</p></section>` : '');
  return `<div class="generated-wrap">${feasibilityBanner}<div class="status-strip"><div><span class="live-dot"></span><strong>${selectedErrors.length ? 'Timetable generation stopped — infeasible' : 'Class timetable generated'}</strong><small>${classSubjects.length} subjects · ${requestedHours} requested hours · ${filled}/48 periods filled${unallocated ? ` · ${unallocated} unallocated` : ''}</small></div><div class="diagnostics"><span class="diag ${errors ? 'bad' : 'good'}">${errors} unresolved</span><span class="diag ${warnings ? 'warn' : 'good'}">${warnings} warnings</span></div></div><section class="card document-details"><div><div class="section-kicker">EXPORT DETAILS</div><h2>RPSIT document information</h2><p>These values appear above the timetable in the PDF.</p></div><div class="details-grid"><label>Document ID<input id="document-id" value="${esc(model.metadata?.documentId || '')}" placeholder="2026-27/ODD/RPSIT/AI&DS/TT/01"></label><label>Document Name<input id="document-name" value="${esc(model.metadata?.documentName || 'Time Table')}" placeholder="Time Table"></label><label>Programme<input id="programme" value="${esc(model.metadata?.programme || schedule.className)}" placeholder="B. TECH. – AI&DS"></label><label>Regulation<input id="regulation" value="${esc(model.metadata?.regulation || 'R-2024')}" placeholder="R-2024"></label><label>Academic year<input id="academic-year" value="${esc(model.metadata?.academicYear || '2026-2027')}" placeholder="2026-2027"></label><label>Odd / Even<input id="odd-even" value="${esc(model.metadata?.oddEven || 'ODD')}" placeholder="ODD"></label><label>W.e.f<input id="effective-date" value="${esc(model.metadata?.effectiveDate || '')}" placeholder="22-06-2026"></label><label>Class Advisor<input id="class-advisor" value="${esc(model.metadata?.classAdvisor || '')}" placeholder="Class advisor"></label></div></section><section class="card subjects-card generated-subjects"><div class="section-kicker">SUBJECT PLACEMENT</div><h2>Monday to Saturday distribution</h2><p>Theory is placed as separate periods. LB hours remain continuous.</p><div class="subject-list">${subjectSummary}</div></section>${labPlan}<div class="timetable-card card"><div class="grid-head"><div class="day-head">DAY / HOURS</div>${header}</div>${rows}</div><section class="insight-grid"><div class="card insight"><span class="insight-icon ${unallocated ? 'amber' : ''}">${unallocated ? '!' : '✓'}</span><div><strong>${unallocated ? `${unallocated} slots remain unallocated` : 'All 48 teaching slots filled'}</strong><small>${capacityMessage}</small></div></div><div class="card insight"><span class="insight-icon amber">!</span><div><strong>Review rule diagnostics</strong><small>HOD/CC first-hour exclusions and soft preference warnings remain visible.</small></div></div></section><div class="floating-actions"><button id="export-button" class="button primary">Show / Export PDF <span>↗</span></button><button id="allocate-button" class="button secondary">Allocate Remaining Periods</button><button id="manual-button" class="button ghost">Edit Subject / Teacher</button></div></div>`;
}

export function renderTeacherTimetable(result, model, selectedTeacher = '') {
  const teachers = Object.values(model.teachers || {});
  const teacherName = selectedTeacher || teachers[0]?.name || '';
  const headers = ['DAY / HOURS', ...Array.from({ length: 8 }, (_, index) => `P${index + 1}`)];
  const rows = DAYS.map(day => `<div class="secondary-row teacher-secondary-row"><div><strong>${day}</strong></div>${Array.from({ length: 8 }, (_, period) => { const assignments = Object.values(result.schedules).map(schedule => { const cell = schedule[day]?.[period]; return cell?.teacher === teacherName ? `${cell.subjectName || cell.acronym || cell.subjectCode} · ${schedule.className}` : ''; }).filter(Boolean); return `<span>${assignments.length ? assignments.map(esc).join('<br>') : '—'}</span>`; }).join('')}</div>`).join('');
  return `<div class="generated-wrap"><div class="view-heading"><div><div class="section-kicker">STAFF TIMETABLE</div><h2>Individual timetable</h2><p>All classes and subjects assigned to one staff member are combined in this weekly view.</p></div><div class="teacher-actions"><label>Staff member<select id="teacher-selector">${teachers.map(teacher => `<option value="${esc(teacher.name)}" ${teacher.name === teacherName ? 'selected' : ''}>${esc(teacher.name)}</option>`).join('')}</select></label><button id="teacher-export-button" class="button primary">Print / Save PDF ↗</button></div></div><section class="card secondary-table teacher-table"><div class="secondary-head teacher-secondary-head">${headers.map(header => `<span>${header}</span>`).join('')}</div>${rows || '<div class="empty-view">No teacher assignments are available yet.</div>'}</section></div>`;
}

export function renderLabTimetable(result, model, className) {
  const subjects = model.subjects.filter(subject => subject.className === className && subject.labPeriods > 0);
  const rows = subjects.map(subject => `<div class="secondary-row lab-secondary-row"><div><strong>${esc(subject.acronym || subject.code)}</strong><small>${esc(subject.name)}</small><small>${esc(subject.teacher)}</small></div>${DAYS.map(day => { const periods = result.schedules[className][day].filter(cell => cell?.subjectId === subject.id && cell.kind === 'lab').map(cell => cell.period + 1); return `<span>${periods.length ? `LB P${Math.min(...periods)}–P${Math.max(...periods)}` : '—'}</span>`; }).join('')}</div>`).join('');
  return `<div class="generated-wrap"><div class="view-heading"><div><div class="section-kicker">LAB TIMETABLE</div><h2>Continuous laboratory blocks · ${esc(className)}</h2><p>Every lab is shown as one block on its assigned day. Fixed lab days from Excel are preserved.</p></div></div><section class="card secondary-table lab-secondary-table"><div class="secondary-head lab-secondary-head"><span>LAB / FACULTY</span>${DAYS.map(day => `<span>${day}</span>`).join('')}</div>${rows || '<div class="empty-view">No lab subjects are available for this class.</div>'}</section></div>`;
}

export function renderConflictPanel(diagnostic) {
  return `<aside class="conflict-panel"><button class="close-panel" data-close-panel>×</button><div class="section-kicker">CONFLICT DETECTOR</div><h2>${esc(diagnostic.rule)}</h2><p>${esc(diagnostic.message)}</p><div class="suggestion"><span class="suggestion-icon">✦</span><div><b>Fixer suggestion</b><span>Try the next valid slot on a different day, preserving the subject spread.</span></div></div><div class="panel-actions"><button class="button secondary" data-reject-conflict>Keep for review</button><button class="button primary" data-approve-conflict>Apply suggestion</button></div></aside>`;
}

export function renderManualPanel(cell, day, period, model, className) {
  const subjects = model.subjects.filter(subject => subject.className === className);
  return `<aside class="conflict-panel manual-panel"><button class="close-panel" data-close-panel>×</button><div class="section-kicker">MANUAL EDIT</div><h2>${esc(day)} · Period ${period + 1}</h2><p>Change both the subject and assigned teacher for this cell.</p><label>Subject<select id="manual-subject">${subjects.map(subject => `<option value="${esc(subject.id)}" ${subject.id === cell?.subjectId ? 'selected' : ''}>${esc(subject.acronym || subject.code)} · ${esc(subject.name)}</option>`).join('')}</select></label><label>Teacher<select id="manual-teacher">${Object.values(model.teachers).map(teacher => `<option value="${esc(teacher.name)}" ${teacher.name === cell?.teacher ? 'selected' : ''}>${esc(teacher.name)}</option>`).join('')}</select></label><div class="panel-actions"><button class="button secondary" data-close-panel>Cancel</button><button class="button primary" data-save-manual data-day="${day}" data-period="${period}">Save cell</button></div></aside>`;
}
